// Caller says which commit it deployed; each container says what it is
// running. Anything other than an exact match on ALL FOUR is a failed
// deploy — including the healthy-but-old container, which is exactly the
// failure a liveness check cannot see.
const body = $input.first().json.body || {};
const want = body.commit || '';
const env = body.env || 'uat';
const targets = [
  { name: 'api',           url: `http://api-${env}:4000/api/version` },
  { name: 'consumer',      url: `http://consumer-${env}:3008/api/version` },
  { name: 'authenticator', url: `http://authenticator-${env}:3001/api/version` },
  { name: 'admin',         url: `http://admin-${env}:3003/api/version` },
];

if (!want) {
  return [{ json: { ok: false, text: `❌ Certifine ${env}: caller 冇畀 commit，驗唔到。` } }];
}

const bad = [];
const seen = [];
for (const t of targets) {
  try {
    const r = await this.helpers.httpRequest({ url: t.url, timeout: 8000, json: true });
    seen.push(`${t.name}=${String(r.commit).slice(0, 8)}`);
    if (r.commit !== want) bad.push(`${t.name} 行緊 ${String(r.commit).slice(0, 8)}`);
  } catch (e) {
    const msg = String(e.message || e);
    bad.push(`${t.name} ${msg.includes('404') ? '冇 /api/version（image 太舊）' : '連唔到'}`);
  }
}

const ok = bad.length === 0;
return [{ json: {
  ok, env, want, seen,
  text: ok
    ? `✅ Certifine ${env} deploy 生效，四個容器都係 ${want.slice(0, 8)}`
    : `❌ Certifine ${env} deploy 未生效（應該係 ${want.slice(0, 8)}）：\n` + bad.map((b) => `• ${b}`).join('\n'),
}}];
